define(["jquery"],function($){"use strict";let summaryLoading=false;function showPopover(count){let $popover=$("#kopere-password-admin-popover");if($popover.length===0){$popover=$(`
                <div id="kopere-password-admin-popover" role="status" aria-live="polite">
                    <div class="kopere-password-admin-popover-title"></div>
                    <div class="kopere-password-admin-popover-body"></div>
                    <div class="kopere-password-admin-popover-actions">
                        <a class="btn btn-primary btn-sm" href=""></a>
                    </div>
                </div>
            `);$("body").append($popover)}$popover.find(".kopere-password-admin-popover-title").text(M.util.get_string("admin_popover_title","proctoringpolicy_password"));$popover.find(".kopere-password-admin-popover-body").text(M.util.get_string("admin_popover_body","proctoringpolicy_password",count));$popover.find("a").attr("href",`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/admin.php`).attr("target","_blank").text(M.util.get_string("admin_popover_open","proctoringpolicy_password"));$popover.show()}function hidePopover(){$("#kopere-password-admin-popover").hide()}function getQuizPendingRegion(){let $region=$("#kopere-password-quiz-pending");if($region.length){return $region}let $target=$(".quizattemptcounts").first();if($target.length===0){return $()}$region=$('<div id="kopere-password-quiz-pending" data-region="kopere-password-quiz-pending"></div>');$target.after($region);return $region}function hideQuizSummary(){$("#kopere-password-quiz-pending").empty().hide()}function refreshQuizSummary(){var isquizview=window.location.href.includes("/mod/quiz/view.php");if(!isquizview||summaryLoading){return}let $region=getQuizPendingRegion();if($region.length===0){return}summaryLoading=true;$.ajax({url:`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/admin.php?ajax=1&summary=1&sesskey=${M.cfg.sesskey}`,method:"GET",dataType:"json",cache:false}).done(function(response){if(!response||!response.html||Number(response.count||0)<=0){hideQuizSummary();return}$region.html(response.html).show()}).always(function(){summaryLoading=false})}function checkPending(){if(window.location.href.includes("/local/kopere_proctoring/policy/password/admin.php")){return}$.ajax({url:`${M.cfg.wwwroot}/local/kopere_proctoring/policy/password/pending.php`,method:"GET",dataType:"json",cache:false,data:{_:Date.now()}}).done(function(response){let total=Number(response&&response.total?response.total:0);if(total>0){showPopover(total);refreshQuizSummary();return}hidePopover();hideQuizSummary()})}function init(){checkPending();window.setInterval(function(){checkPending()},Number(5e3))}return{init:init}});